const { rows } = require('./_state');

function getInvoice(id) {
  const r = rows.get(id);
  return r ? { ...r } : null;
}

function createInvoice(id, customerId, cents) {
  const inv = { id, customerId, cents, status: 'open' };
  rows.set(id, inv);
  return { ...inv };
}

function markPaid(id) {
  const r = rows.get(id);
  if (!r) return null;
  r.status = 'paid';
  return { ...r };
}

module.exports = { getInvoice, createInvoice, markPaid };

