const store = require('../store');

function settleInvoice(id) {
  const inv = store.getInvoice(id);
  if (!inv) throw new Error('unknown invoice: ' + id);
  if (inv.status === 'paid') return { settled: false, invoice: inv };
  return { settled: true, invoice: store.markPaid(id) };
}

module.exports = { settleInvoice };

